130	    /**
131	     * Registers a new *local* user (e-mail + password).
132	     *
133	     * @throws RegistrationError if the e-mail is already taken or the
134	     *         password does not meet security requirements.
135	     */
136	    [[nodiscard]]
137	    AuthResult registerLocal(const RegisterRequest& req) const
138	    {
139	        validateEmail(req.email);
140	
141	        if (m_userRepo->findByEmail(req.email))
142	            throw RegistrationError{"E-mail is already registered"};
143	
144	        validatePassword(req.password);
145	
146	        const auto hashed = m_passwordHasher->hash(req.password);
147	        auto user         = domain::entities::User::createLocal(
148	                                domain::entities::Email  {req.email},
149	                                hashed,
150	                                req.displayName.value_or(""));
151	
152	        m_userRepo->save(user);
153	
154	        return generateAuthResult(user);
155	    }
156	
157	    /**
158	     * Authenticates a user through local credentials.
159	     *
160	     * @throws AuthenticationError on invalid credentials.
161	     */
162	    [[nodiscard]]
163	    AuthResult loginLocal(const std::string& email,
164	                          const std::string& password) const
165	    {
166	        const auto stored = m_userRepo->findByEmail(email);
167	        if (!stored || !stored->isLocalAccount())
168	            throw AuthenticationError{"Invalid credentials"};
169	
170	        if (!m_passwordHasher->verify(password, stored->passwordHash()))
171	            throw AuthenticationError{"Invalid credentials"};
172	
173	        return generateAuthResult(*stored);
174	    }
