176	    /**
177	     * Authenticates a user through a social provider (Google, Apple,
178	     * GitHub, …).
179	     *
180	     * The returned user is automatically provisioned if this is the
181	     * first time he/she signs in.
182	     *
183	     * @throws AuthenticationError on invalid/expired tokens.
184	     */
185	    [[nodiscard]]
186	    AuthResult loginWithSocial(domain::ports::OAuthProvider provider,
187	                               const std::string&           accessToken) const
188	    {
189	        auto profile = m_oauthGateway->fetchProfile(provider, accessToken);
190	        if (!profile)
191	            throw AuthenticationError{"Unable to fetch social profile"};
192	
193	        auto user = m_userRepo->findByOauth(provider, profile->id);
194	        if (!user)
195	        {
196	            // First time ever: provision account
197	            user.emplace(domain::entities::User::createSocial(
198	                provider,
199	                profile->id,
200	                profile->email,
201	                profile->displayName));
202	            m_userRepo->save(*user);
203	        }
204	
205	        return generateAuthResult(*user);
206	    }
207	
208	    /**
209	     * Retrieves a user by id.
210	     */
211	    [[nodiscard]]
212	    std::optional<domain::entities::User>
213	    findUserById(const domain::entities::UserId& id) const
214	    {
215	        return m_userRepo->findById(id);
216	    }
