219	    // -----------------------------------------------------------------
220	    // Helpers
221	    // -----------------------------------------------------------------
222	
223	    static void validateEmail(const std::string& email)
224	    {
225	        // Very naïve validation; replace with RFC-5322 compliance check
226	        const auto at = email.find('@');
227	        if (at == std::string::npos || at == 0 || at == email.size() - 1)
228	            throw RegistrationError{"Invalid e-mail format"};
229	    }
230	
231	    static void validatePassword(const std::string& pw)
232	    {
233	        // Example rules: ≥ 8 chars, at least one digit, one letter
234	        if (pw.size() < 8)
235	            throw RegistrationError{"Password too short (minimum 8 characters)"};
236	
237	        bool hasDigit = false, hasAlpha = false;
238	        for (char c : pw)
239	        {
240	            if (std::isdigit(static_cast<unsigned char>(c))) hasDigit = true;
241	            if (std::isalpha(static_cast<unsigned char>(c))) hasAlpha = true;
242	        }
243	        if (!hasDigit || !hasAlpha)
244	            throw RegistrationError{"Password must contain letters and digits"};
245	    }
