247	    [[nodiscard]]
248	    AuthResult generateAuthResult(const domain::entities::User& user) const
249	    {
250	        constexpr auto kExpiry = std::chrono::hours{2};
251	        const auto token = m_tokenGenerator->issueToken(user.id(), kExpiry);
252	
253	        return AuthResult{user, token, Clock::now(), kExpiry};
254	    }
