35	/**
36	 * Strong typed identifier wrapper.
37	 *
38	 * This idiom prevents accidental mixing of identifiers that are represented by
39	 * the same underlying type (e.g. `uint64_t`).
40	 */
41	template <typename Tag>
42	class Id {
43	public:
44	    using underlying_type = std::uint64_t;
45	
46	    constexpr Id() noexcept = default;
47	    explicit constexpr Id(underlying_type v) noexcept : _value{v} {}
48	
49	    constexpr underlying_type value() const noexcept { return _value; }
50	
51	    // Comparisons
52	    constexpr auto operator<=>(const Id&) const noexcept = default;
53	
54	    // Hash support
55	    struct Hasher {
56	        constexpr std::size_t operator()(const Id& id) const noexcept {
57	            return std::hash<underlying_type>{}(id._value);
58	        }
59	    };
60	
61	private:
62	    underlying_type _value{};
63	};
