76	/**
77	 * Money is a value object representing an amount in the smallest denomination
78	 * (cents, pence, etc.).  Arithmetic operators enforce currency safety.
79	 */
80	class Money {
81	public:
82	    constexpr Money(std::int64_t cents = 0, Currency currency = Currency::USD)
83	        : _cents{cents}, _currency{currency} {}
84	
85	    constexpr Currency currency() const noexcept { return _currency; }
86	    constexpr std::int64_t cents() const noexcept { return _cents; }
87	
88	    // Arithmetic – currency must match, otherwise throws
89	    [[nodiscard]]
90	    constexpr Money operator+(const Money& other) const {
91	        verify_same_currency(other);
92	        return Money{_cents + other._cents, _currency};
93	    }
94	
95	    [[nodiscard]]
96	    constexpr Money operator-(const Money& other) const {
97	        verify_same_currency(other);
98	        return Money{_cents - other._cents, _currency};
99	    }
100	
101	    [[nodiscard]]
102	    constexpr Money operator*(std::int64_t factor) const {
103	        return Money{_cents * factor, _currency};
104	    }
105	
106	    constexpr auto operator<=>(const Money&) const = default;
107	
108	private:
109	    constexpr void verify_same_currency(const Money& other) const {
110	        if (other._currency != _currency) {
111	            throw std::logic_error{"Currency mismatch"};
112	        }
113	    }
114	
115	    std::int64_t _cents;
116	    Currency     _currency;
117	};
