201	class Cart final {
202	public:
203	    explicit Cart(CartId id, UserId user_id) : _id{id}, _user_id{user_id} {}
204	
205	    CartId id() const noexcept { return _id; }
206	    UserId user_id() const noexcept { return _user_id; }
207	
208	    std::size_t items_count() const noexcept { return _items.size(); }
209	    const std::vector<CartItem>& items() const noexcept { return _items; }
210	
211	    // Adds or updates an item
212	    void add_item(const Product& product, std::uint32_t qty) {
213	        if (qty == 0) { throw InvalidQuantity{"Quantity must be > 0"}; }
214	
215	        auto it = std::find_if(
216	            _items.begin(), _items.end(),
217	            [&](const CartItem& item) { return item.product_id() == product.id(); });
218	
219	        if (it == _items.end()) {
220	            _items.emplace_back(product.id(), product.price(), qty);
221	        } else {
222	            it->change_quantity(it->quantity() + qty);
223	        }
224	    }
225	
226	    void remove_item(ProductId product_id) {
227	        auto it = std::remove_if(
228	            _items.begin(), _items.end(),
229	            [&](const CartItem& item) { return item.product_id() == product_id; });
230	        _items.erase(it, _items.end());
231	    }
232	
233	    Money total() const {
234	        return std::accumulate(
235	            _items.begin(), _items.end(), Money{0, Currency::USD},
236	            [](const Money& acc, const CartItem& item) { return acc + item.subtotal(); });
237	    }
238	
239	private:
240	    CartId                  _id;
241	    UserId                  _user_id;
242	    std::vector<CartItem>   _items;
243	};
