303	/**
304	 * CartService contains behaviors that involve multiple aggregates (Product and
305	 * Cart) plus side effects (publishing an event).  Keeping this logic in a
306	 * dedicated service keeps entities lightweight.
307	 */
308	class CartService final {
309	public:
310	    CartService(ProductRepository& product_repo,
311	                CartRepository& cart_repo,
312	                EventPublisher& publisher)
313	        : _product_repo{product_repo},
314	          _cart_repo{cart_repo},
315	          _publisher{publisher} {}
316	
317	    /**
318	     * Add a product to the user's cart, checking inventory and emitting an event.
319	     */
320	    void add_product_to_cart(CartId cart_id, ProductId product_id, std::uint32_t qty) {
321	        if (qty == 0) { throw InvalidQuantity{"Quantity must be > 0"}; }
322	
323	        auto product_opt = _product_repo.find(product_id);
324	        if (!product_opt) { throw ProductNotFound{"Product does not exist"}; }
325	
326	        auto cart_opt = _cart_repo.find(cart_id);
327	        if (!cart_opt) { throw DomainError{"Cart not found"}; }
328	
329	        Product& product = *product_opt; // not const – inventory may change
330	        if (qty > product.inventory()) {
331	            throw InsufficientInventory{"Not enough inventory"};
332	        }
333	        product.decrease_inventory(qty);
334	
335	        Cart& cart = *cart_opt;
336	        cart.add_item(product, qty);
337	
338	        // Persist both aggregates
339	        _product_repo.save(product);
340	        _cart_repo.save(cart);
341	
342	        // Emit event
343	        _publisher.publish(ProductAddedToCart{
344	            .cart_id   = cart_id,
345	            .product_id= product_id,
346	            .quantity  = qty
347	        });
348	    }
349	
350	private:
351	    ProductRepository& _product_repo;
352	    CartRepository&    _cart_repo;
353	    EventPublisher&    _publisher;
354	};
