73	/**
74	 * Password hasher that prefixes any plain text with a constant marker so we
75	 * can later assert that hashing was actually performed.
76	 */
77	class NoopPasswordHasher final : public IPasswordHasher
78	{
79	public:
80	    std::string hash(const std::string& plain) override
81	    {
82	        ++_hashCalls;
83	        return kPrefix + plain;
84	    }
85	
86	    bool verify(const std::string& plain,
87	                const std::string& hashed) override
88	    {
89	        ++_verifyCalls;
90	        return hashed == hash(plain);
91	    }
92	
93	    std::size_t hashCalls()   const noexcept { return _hashCalls;   }
94	    std::size_t verifyCalls() const noexcept { return _verifyCalls; }
95	
96	private:
97	    static constexpr const char* kPrefix = "hashed:";
98	    std::size_t _hashCalls{0};
99	    std::size_t _verifyCalls{0};
100	};
