57	/**
58	 * A lightweight RAII wrapper around `sqlite3_stmt*`.
59	 * Finalizes the statement when going out of scope.
60	 */
61	class stmt final
62	{
63	public:
64	    stmt(sqlite3* db, const std::string& sql)
65	        : _stmt{nullptr}
66	    {
67	        if (sqlite3_prepare_v2(db, sql.c_str(), static_cast<int>(sql.size()), &_stmt, nullptr) !=
68	            SQLITE_OK)
69	        {
70	            throw std::runtime_error{std::string{"Failed to prepare statement: "} +
71	                                     sqlite3_errmsg(db)};
72	        }
73	    }
74	
75	    stmt(const stmt&)            = delete;
76	    stmt& operator=(const stmt&) = delete;
77	
78	    stmt(stmt&& other) noexcept : _stmt{other._stmt} { other._stmt = nullptr; }
79	
80	    stmt& operator=(stmt&& other) noexcept
81	    {
82	        if (this != &other) {
83	            finalize();
84	            _stmt       = other._stmt;
85	            other._stmt = nullptr;
86	        }
87	        return *this;
88	    }
89	
90	    ~stmt() { finalize(); }
91	
92	    sqlite3_stmt* get() noexcept { return _stmt; }
93	
94	private:
95	    void finalize() noexcept
96	    {
97	        if (_stmt) { sqlite3_finalize(_stmt); }
98	        _stmt = nullptr;
99	    }
100	
101	    sqlite3_stmt* _stmt;
102	};
