106	/*==================================================================================================
107	 *  Connection Pool (very small & naive on purpose)
108	 *================================================================================================*/
109	
110	class SqliteConnectionPool
111	{
112	public:
113	    explicit SqliteConnectionPool(std::string database_file, std::size_t pool_size = 4)
114	        : _db_file{std::move(database_file)}, _capacity{pool_size}
115	    {
116	        // Pre-open a few connections so the first requests are fast.
117	        for (std::size_t i = 0; i < _capacity; ++i) {
118	            _available.emplace_back(open_connection());
119	        }
120	    }
121	
122	    SqliteConnectionPool(const SqliteConnectionPool&)            = delete;
123	    SqliteConnectionPool& operator=(const SqliteConnectionPool&) = delete;
124	
125	    /**
126	     * Acquire a connection from the pool.
127	     * The caller gets a std::shared_ptr so multiple readers can share the same handle
128	     * simultaneously (SQLite supports it as long as they do not write).
129	     */
130	    std::shared_ptr<sqlite3> acquire()
131	    {
132	        std::scoped_lock lk{_mtx};
133	
134	        if (_available.empty()) {
135	            // No free handle; open a new one (slow path).
136	            return open_connection();
137	        }
138	
139	        auto db = _available.back();
140	        _available.pop_back();
141	        return db;
142	    }
143	
144	    /**
145	     * Return a connection back to the pool.
146	     */
147	    void release(std::shared_ptr<sqlite3> db)
148	    {
149	        std::scoped_lock lk{_mtx};
150	        if (_available.size() < _capacity) {
151	            _available.emplace_back(std::move(db));
152	        }
153	        // else drop the connection on the floor (dtor will close).
154	    }
155	
156	private:
157	    std::shared_ptr<sqlite3> open_connection() const
158	    {
159	        sqlite3* raw = nullptr;
160	        if (sqlite3_open_v2(
161	                _db_file.c_str(),
162	                &raw,
163	                SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX,
164	                nullptr) != SQLITE_OK)
165	        {
166	            throw std::runtime_error{"Unable to open SQLite database: " + _db_file};
167	        }
168	
169	        // Wrap the raw pointer with custom deleter.
170	        return {raw, detail::sqlite_deleter{}};
171	    }
172	
173	    const std::string                     _db_file;
174	    const std::size_t                     _capacity;
175	    std::vector<std::shared_ptr<sqlite3>> _available;
176	    mutable std::mutex                    _mtx;
177	};
