198	    std::optional<domain::Product> get_product_by_id(domain::ProductId id) override
199	    {
200	        const std::string sql =
201	            "SELECT id, sku, name, description, price_cents "
202	            "FROM products WHERE id = ?1 AND deleted_at IS NULL";
203	
204	        return with_connection<std::optional<domain::Product>>(
205	            [&sql, &id](sqlite3* db) -> std::optional<domain::Product> {
206	                detail::stmt stmt{db, sql};
207	                sqlite3_bind_int64(stmt.get(), 1, static_cast<sqlite3_int64>(id.value()));
208	
209	                if (sqlite3_step(stmt.get()) == SQLITE_ROW) {
210	                    return domain::Product{
211	                        domain::ProductId{sqlite3_column_int64(stmt.get(), 0)},
212	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 1)),
213	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 2)),
214	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 3)),
215	                        static_cast<std::uint32_t>(sqlite3_column_int(stmt.get(), 4))};
216	                }
217	
218	                return std::nullopt;
219	            });
