226	            "WHERE (name LIKE '%' || ?1 || '%' OR description LIKE '%' || ?1 || '%') "
227	            "      AND deleted_at IS NULL "
228	            "ORDER BY name ASC LIMIT 50";
229	
230	        return with_connection<std::vector<domain::Product>>(
231	            [&sql, &free_text](sqlite3* db) {
232	                std::vector<domain::Product> rows;
233	                detail::stmt               stmt{db, sql};
234	                sqlite3_bind_text(stmt.get(), 1, free_text.c_str(),
235	                                  static_cast<int>(free_text.size()), SQLITE_TRANSIENT);
236	
237	                while (sqlite3_step(stmt.get()) == SQLITE_ROW) {
238	                    rows.emplace_back(domain::Product{
239	                        domain::ProductId{sqlite3_column_int64(stmt.get(), 0)},
240	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 1)),
241	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 2)),
242	                        reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 3)),
243	                        static_cast<std::uint32_t>(sqlite3_column_int(stmt.get(), 4))});
