253	    void save_order(const domain::Order& order) override
254	    {
255	        const std::string order_sql =
256	            "INSERT INTO orders (id, user_id, total_cents, created_at) "
257	            "VALUES (?1, ?2, ?3, ?4)";
258	
259	        const std::string line_sql =
260	            "INSERT INTO order_lines (order_id, product_id, quantity, unit_price_cents) "
261	            "VALUES (?1, ?2, ?3, ?4)";
262	
263	        with_connection<void>([&](sqlite3* db) {
264	            // Wrap in transaction.
265	            exec_simple(db, "BEGIN TRANSACTION");
266	
267	            try {
268	                // Insert order
269	                {
270	                    detail::stmt stmt{db, order_sql};
271	                    sqlite3_bind_int64(stmt.get(), 1,
272	                                       static_cast<sqlite3_int64>(order.id().value()));
273	                    sqlite3_bind_int64(stmt.get(), 2,
274	                                       static_cast<sqlite3_int64>(order.user_id().value()));
275	                    sqlite3_bind_int64(stmt.get(), 3, order.total_cents());
276	                    sqlite3_bind_int64(stmt.get(), 4,
277	                                       static_cast<sqlite3_int64>(
278	                                           std::chrono::duration_cast<std::chrono::seconds>(
279	                                               order.created_at().time_since_epoch())
280	                                               .count()));
281	
282	                    if (sqlite3_step(stmt.get()) != SQLITE_DONE) {
283	                        throw std::runtime_error{"Failed to insert order"};
284	                    }
285	                }
286	
287	                // Insert lines
288	                for (const auto& l : order.lines()) {
289	                    detail::stmt stmt{db, line_sql};
290	                    sqlite3_bind_int64(stmt.get(), 1,
291	                                       static_cast<sqlite3_int64>(order.id().value()));
292	                    sqlite3_bind_int64(stmt.get(), 2,
293	                                       static_cast<sqlite3_int64>(l.product_id.value()));
294	                    sqlite3_bind_int(stmt.get(), 3, l.quantity);
295	                    sqlite3_bind_int(stmt.get(), 4, l.unit_price_cents);
296	
297	                    if (sqlite3_step(stmt.get()) != SQLITE_DONE) {
298	                        throw std::runtime_error{"Failed to insert order lines"};
299	                    }
300	                }
301	
302	                exec_simple(db, "COMMIT");
303	            } catch (...) {
304	                exec_simple(db, "ROLLBACK");
305	                throw;  // re-throw to service layer
306	            }
307	        });
308	    }
