323	                sqlite3_bind_text(stmt.get(), 1, token.c_str(), static_cast<int>(token.size()),
324	                                  SQLITE_TRANSIENT);
325	
326	                if (sqlite3_step(stmt.get()) == SQLITE_ROW) {
327	                    domain::UserSession sess;
328	                    sess.token   = reinterpret_cast<const char*>(sqlite3_column_text(stmt.get(), 0));
329	                    sess.user_id = domain::UserId{sqlite3_column_int64(stmt.get(), 1)};
330	                    auto seconds = sqlite3_column_int64(stmt.get(), 2);
331	                    sess.expires_at =
332	                        std::chrono::system_clock::time_point{std::chrono::seconds{seconds}};
333	                    return sess;
334	                }
335	
336	                return std::nullopt;
337	            });
338	    }
