340	    void store_session(const domain::UserSession& session) override
341	    {
342	        const std::string sql =
343	            "INSERT INTO sessions (token, user_id, expires_at) VALUES (?1, ?2, ?3)";
344	
345	        with_connection<void>([&](sqlite3* db) {
346	            detail::stmt stmt{db, sql};
347	            sqlite3_bind_text(stmt.get(), 1, session.token.c_str(),
348	                              static_cast<int>(session.token.size()), SQLITE_TRANSIENT);
349	            sqlite3_bind_int64(stmt.get(), 2,
350	                               static_cast<sqlite3_int64>(session.user_id.value()));
351	            auto seconds = std::chrono::duration_cast<std::chrono::seconds>(
352	                               session.expires_at.time_since_epoch())
353	                               .count();
354	            sqlite3_bind_int64(stmt.get(), 3, seconds);
355	
356	            if (sqlite3_step(stmt.get()) != SQLITE_DONE) {
357	                throw std::runtime_error{
358	                    std::string{"Failed to insert session: "} + sqlite3_errmsg(db)};
359	            }
360	        });
361	    }
