368	    template <typename T = void>
369	    T with_connection(std::function<T(sqlite3*)> fn)
370	    {
371	        auto conn = _pool.acquire();
372	        try {
373	            T result = fn(conn.get());
374	            _pool.release(conn);
375	            return result;
376	        } catch (...) {
377	            _pool.release(conn);
378	            throw;
379	        }
380	    }
