382	    static void exec_simple(sqlite3* db, const char* sql)
383	    {
384	        if (sqlite3_exec(db, sql, nullptr, nullptr, nullptr) != SQLITE_OK) {
385	            throw std::runtime_error{std::string{"SQLite error: "} + sqlite3_errmsg(db)};
386	        }
387	    }
