406	            "  user_id INTEGER NOT NULL,"
407	            "  total_cents INTEGER NOT NULL,"
408	            "  created_at INTEGER NOT NULL"
409	            ");",
410	
411	            "CREATE TABLE IF NOT EXISTS order_lines ("
